    public function testRetrieveEnrichmentMetrics(): void
    {
        $this->queueJson(200, '{"events_ingested":128450,"events_rejected":214,"enrichment_lookups":41230,"enrichment_cache_hits":40118,"enrichment_provider_calls":1112,"enrichment_skipped_low_value":74320,"unique_ips_seen":1112,"period_days":30,"cache_hit_rate":0.973,"unique_ip_ratio":0.0087,"provider_calls_per_1k_events":8.66}');

        $result = $this->client->monitoringEvents->retrieveEnrichmentMetrics([
            'days' => 1,
        ]);

        $request = $this->lastRequest();
        self::assertSame('GET', $request->getMethod());
        self::assertSame('verification.didit.me', $request->getUri()->getHost());
        self::assertSame('/v3/events/enrichment-metrics/', $request->getUri()->getPath());
        self::assertSame([
            'days' => '1',
        ], $this->queryParams($request));
        self::assertSame(self::API_KEY, $request->getHeaderLine('x-api-key'));
        self::assertSame('', (string) $request->getBody());
        self::assertSame(200, $result->rawResponse()?->status);
        self::assertSame($this->decoded('{"events_ingested":128450,"events_rejected":214,"enrichment_lookups":41230,"enrichment_cache_hits":40118,"enrichment_provider_calls":1112,"enrichment_skipped_low_value":74320,"unique_ips_seen":1112,"period_days":30,"cache_hit_rate":0.973,"unique_ip_ratio":0.0087,"provider_calls_per_1k_events":8.66}'), $result->toArray());
        self::assertSame(128450, $result->eventsIngested);
    }

